function [j, e] = elem2vectors(ecc, inc, om, w)
%ELEM2VECTORS  thirdbody.secular.elem2vectors(a, ecc, inc, Om, w): the angular-momentum vector j (|j| = sqrt(1 - e^2)) and the
%   eccentricity vector e of classical elements [rad].
%   ecc: real[1] (passed a plain number)
%   inc: real[1] (passed a plain number)
%   om: real[1] (passed a plain number)
%   w: real[1] (passed a plain number)
%   returns j: real[1][3] (passed a plain number)
%   returns e: real[1][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    j = zeros(3, 1);
    e = zeros(3, 1);
    ci = cos(inc);
    si = sin(inc);
    co = cos(om);
    so = sin(om);
    jhat = [(so * si); ((-(co)) * si); ci];
    node = [co; so; 0];
    ip = asils.pc.cross_(jhat, node);
    cw = cos(w);
    sw = sin(w);
    ehat = [((cw * node(1)) + (sw * ip(1))); ((cw * node(2)) + (sw * ip(2))); ((cw * node(3)) + (sw * ip(3)))];
    sj = asils.pc.sqrt_((1 - (ecc * ecc)));
    j = [(sj * jhat(1)); (sj * jhat(2)); (sj * jhat(3))];
    e = [(ecc * ehat(1)); (ecc * ehat(2)); (ecc * ehat(3))];
end
